<?php
declare(strict_types=1);
namespace App\Controller;
use App\Core\Controller;use App\Core\Response;use App\Repository\DispositivoRepository;use App\Repository\ClienteRepository;use App\Repository\SedeRepository;use App\Repository\ProdottoRepository;
final class DispositivoController extends Controller
{
 private function repo(): DispositivoRepository{return new DispositivoRepository($this->ctx->db,$this->aziendaId());}
 public function index(): Response{$dispositivi=$this->repo()->records();return $this->render('dispositivi/index',compact('dispositivi'));}
 public function scan(): Response{return $this->render('dispositivi/scansione');}
 public function create(): Response{$d=['cliente_id'=>$this->ctx->request->query('cliente_id')??'','sede_id'=>$this->ctx->request->query('sede_id')??'','prodotto_id'=>'','codice'=>'','tipo'=>'','modello'=>'','posizione'=>'','descrizione'=>'','latitudine'=>'','longitudine'=>'','installato_il'=>date('Y-m-d'),'stato'=>'attivo','esca'=>''];$sedi=(new SedeRepository($this->ctx->db,$this->aziendaId()))->withCliente();$clienti=(new ClienteRepository($this->ctx->db,$this->aziendaId()))->all('1=1',[],'denominazione');$prodotti=(new ProdottoRepository($this->ctx->db,$this->aziendaId()))->records();return $this->render('dispositivi/form',compact('d','sedi','clienti','prodotti'));}
 public function store(): Response{$d=$this->ctx->request->only(['cliente_id','sede_id','prodotto_id','codice','tipo','modello','posizione','descrizione','latitudine','longitudine','installato_il','stato','esca']);$errors=[];if($d['codice']===''||$d['tipo']==='')$errors[]='Inserisci codice e tipologia.';$sede=ctype_digit($d['sede_id'])?(new SedeRepository($this->ctx->db,$this->aziendaId()))->find((int)$d['sede_id']):null;if(!$sede||($d['cliente_id']!==''&&(int)$sede['cliente_id']!==(int)$d['cliente_id']))$errors[]='Seleziona una sede valida per il cliente.';foreach(['latitudine'=>[-90,90],'longitudine'=>[-180,180]] as $k=>$range)if($d[$k]!==''&&(!is_numeric($d[$k])||(float)$d[$k]<$range[0]||(float)$d[$k]>$range[1]))$errors[]='Coordinate non valide.';if($d['prodotto_id']!==''&&(!ctype_digit($d['prodotto_id'])||!(new ProdottoRepository($this->ctx->db,$this->aziendaId()))->find((int)$d['prodotto_id'])))$errors[]='Il prodotto selezionato non è disponibile.';if($errors)return $this->redirect('/app/dispositivi/nuovo','error',implode(' ',$errors));$d['cliente_id']=$sede['cliente_id'];$d['qr_token']=bin2hex(random_bytes(32));$id=$this->repo()->create($d);$this->ctx->audit->record('creazione','dispositivo',$id);return $this->redirect('/app/dispositivi/'.$id,'ok','Dispositivo registrato. Il QR identifica il dispositivo e richiede l’accesso per aggiungere controlli.');}
 public function show(int $id): Response{$dispositivo=$this->repo()->detail($id)??$this->notFound();$controlli=$this->repo()->checks($id);$prodotti=(new ProdottoRepository($this->ctx->db,$this->aziendaId()))->records();return $this->render('dispositivi/show',compact('dispositivo','controlli','prodotti'));}
 public function fromQr(string $token): Response{$d=$this->repo()->byToken($token)??$this->notFound();return $this->redirect('/app/dispositivi/'.$d['id']);}
 public function byCode(): Response{$code=trim((string)$this->ctx->request->query('codice',''));$d=$this->ctx->db->fetchOne('SELECT id FROM dispositivi WHERE azienda_id=:az AND codice=:c AND archiviato_at IS NULL',['az'=>$this->aziendaId(),'c'=>$code]);if(!$d)return $this->redirect('/app/dispositivi','error','Nessun dispositivo trovato con questo codice.');return $this->redirect('/app/dispositivi/'.$d['id']);}
 public function check(int $id): Response{$this->repo()->find($id)??$this->notFound();$d=$this->ctx->request->only(['esito','attivita','tipo_esca','quantita_esca','consumo','anomalia','note','latitudine','longitudine']);if($d['esito']==='')return $this->redirect('/app/dispositivi/'.$id,'error','Seleziona l’esito del controllo.');if($d['quantita_esca']!==''&&(!is_numeric($d['quantita_esca'])||(float)$d['quantita_esca']<0))return $this->redirect('/app/dispositivi/'.$id,'error','Quantità esca non valida.');foreach(['latitudine'=>[-90,90],'longitudine'=>[-180,180]] as $k=>$range)if($d[$k]!==''&&(!is_numeric($d[$k])||(float)$d[$k]<$range[0]||(float)$d[$k]>$range[1]))$d[$k]='';$this->ctx->db->transaction(function()use($id,$d){$this->ctx->db->insert('controlli_dispositivi',['azienda_id'=>$this->aziendaId(),'dispositivo_id'=>$id,'operatore_id'=>$this->ctx->auth->id(),'esito'=>$d['esito'],'attivita'=>$d['attivita'],'tipo_esca'=>$d['tipo_esca'],'quantita_esca'=>$d['quantita_esca']===''?null:$d['quantita_esca'],'consumo'=>$d['consumo'],'anomalia'=>$d['anomalia'],'note'=>$d['note'],'latitudine'=>$d['latitudine']===''?null:$d['latitudine'],'longitudine'=>$d['longitudine']===''?null:$d['longitudine']]);$this->ctx->db->update('dispositivi',['ultimo_controllo'=>date('Y-m-d H:i:s')],['id'=>$id,'azienda_id'=>$this->aziendaId()]);});$this->ctx->audit->record('controllo_dispositivo','dispositivo',$id,['esito'=>$d['esito']]);return $this->redirect('/app/dispositivi/'.$id,'ok','Controllo registrato nello storico.');}
}
